DROP TABLE IF EXISTS `access_control_face`;
CREATE TABLE `access_control_face` (
  `mf_id` varchar(64) NOT NULL COMMENT '主键ID',
  `machine_id` varchar(64) NOT NULL COMMENT '设备ID',
  `person_id` varchar(30) NOT NULL COMMENT '人员ID',
  `person_type` varchar(12) NOT NULL DEFAULT 'OWNER' COMMENT '人员类型 OWNER 业主 STAFF 员工',
  `name` varchar(200) NOT NULL COMMENT '用户名称',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `face_path` varchar(500) NOT NULL COMMENT '人脸http 地址',
  `id_number` varchar(64) DEFAULT NULL COMMENT '身份证',
  `state` varchar(12) NOT NULL COMMENT '状态',
  `message` varchar(512) NOT NULL COMMENT '消息',
  `community_id` varchar(64) NOT NULL COMMENT '小区ID',
  `card_number` varchar(64) DEFAULT NULL COMMENT '门禁卡号',
  `come_type` varchar(12) NOT NULL COMMENT '来自类型 FLOOR 楼栋授权 OWNER 人员授权 STAFF 员工授权',
  `come_id` varchar(30) NOT NULL DEFAULT '9999' COMMENT '来自ID，通过楼栋授权，人员授权，员工授权',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `room_name` varchar(64) DEFAULT NULL COMMENT '房屋名称',
  PRIMARY KEY (`mf_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

