  UNIQUE KEY `idx_orr_rel_id` (`rel_id`) USING BTREE,
  KEY `idx_borr_b_id` (`b_id`) USING BTREE,
  KEY `idx_orr_b_id` (`b_id`) USING BTREE,
  KEY `i_borr_owner_id` (`owner_id`) USING BTREE,
