-- ----------------------------
-- Table structure for charge_machine_order_acct
-- ----------------------------
DROP TABLE IF EXISTS `charge_machine_order_acct`;
CREATE TABLE `charge_machine_order_acct` (
  `cmoa_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单ID',
  `order_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单ID',
