-- Records of file_rel
-- ----------------------------

-- ----------------------------
-- Table structure for hardware_manufacturer
-- ----------------------------
DROP TABLE IF EXISTS `hardware_manufacturer`;
CREATE TABLE `hardware_manufacturer` (
  `hm_id` varchar(64) NOT NULL COMMENT '厂商ID',
  `hm_name` varchar(200) NOT NULL COMMENT '厂商名称',
  `version` varchar(12) NOT NULL COMMENT '厂商协议版本号',
  `protocol_impl` varchar(200) NOT NULL COMMENT '协议实现 一般 为spring bean名称',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效',
  `hm_type` varchar(12) NOT NULL COMMENT '商户类型，详情请查看 t_dict',
  `author` varchar(64) NOT NULL COMMENT '该协议开发者',
  `link` varchar(11) NOT NULL COMMENT '开发者联系方式',
  `license` longtext NOT NULL COMMENT '该协议许可',
  `prod_url` varchar(500) NOT NULL COMMENT '产品官网',
  `default_protocol` varchar(12) NOT NULL DEFAULT 'F' COMMENT '是否启用该协议，T是，F否',
  PRIMARY KEY (`hm_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

