  `org_level` varchar(10) NOT NULL COMMENT '组织级别1 公司级 2 分公司级，3 部门级 查看t_dict表',
  `parent_org_id` varchar(30) NOT NULL COMMENT '上级组织ID，一级时填写org_id',
  `description` varchar(200) DEFAULT NULL COMMENT '组织描述',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效',
  `belong_community_id` varchar(30) NOT NULL COMMENT '归属小区，9999 归属于入驻的所有小区，否则是为小区ID',
  `allow_operation` varchar(12) NOT NULL DEFAULT 'T' COMMENT '允许前台操作数据，T可以，F不可以',
  PRIMARY KEY (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of u_org
-- ----------------------------

-- ----------------------------
-- Table structure for u_org_community
-- ----------------------------
DROP TABLE IF EXISTS `u_org_community`;
CREATE TABLE `u_org_community` (
  `org_community_id` varchar(30) NOT NULL COMMENT '组织ID',
  `org_id` varchar(30) NOT NULL COMMENT '组织ID',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `community_name` varchar(200) NOT NULL COMMENT '小区名称',
  `b_id` varchar(30) NOT NULL COMMENT '业务Id',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `org_name` varchar(200) NOT NULL COMMENT '组织名称',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of u_org_community
-- ----------------------------

-- ----------------------------
-- Table structure for u_org_staff_rel
-- ----------------------------
DROP TABLE IF EXISTS `u_org_staff_rel`;
CREATE TABLE `u_org_staff_rel` (
  `rel_id` varchar(30) NOT NULL COMMENT '组织员工ID',
  `b_id` varchar(30) DEFAULT NULL COMMENT '业务ID',
  `org_id` varchar(30) NOT NULL COMMENT '组织ID',
  `staff_id` varchar(30) NOT NULL COMMENT '员工ID',
  `rel_cd` varchar(30) NOT NULL COMMENT '关系角色，10000 普通员工， 20000部门经理 查看t_dict表',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID'
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of u_org_staff_rel
-- ----------------------------

-- ----------------------------
-- Table structure for u_role_community
-- ----------------------------
DROP TABLE IF EXISTS `u_role_community`;
CREATE TABLE `u_role_community` (
  `rc_id` varchar(30) NOT NULL COMMENT '主键ID',
  `role_id` varchar(30) NOT NULL COMMENT '权限标志 是 1是权限组 0是权限',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `community_name` varchar(128) NOT NULL COMMENT '小区名称',
  PRIMARY KEY (`rc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of u_role_community
-- ----------------------------

-- ----------------------------
-- Table structure for u_user
-- ----------------------------
DROP TABLE IF EXISTS `u_user`;
CREATE TABLE `u_user` (
  `user_id` varchar(30) NOT NULL COMMENT '用户ID',
  `name` varchar(50) NOT NULL COMMENT '名称',
  `email` varchar(30) DEFAULT NULL COMMENT '邮箱地址',
  `address` varchar(200) DEFAULT NULL COMMENT '现居住地址',
  `password` varchar(128) DEFAULT NULL COMMENT '用户密码，加密过后',
  `sex` varchar(1) DEFAULT NULL COMMENT '性别，0表示男孩 1表示女孩',
  `tel` varchar(11) NOT NULL,
  `level_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '用户级别,关联user_level',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `face_url` varchar(512) DEFAULT NULL COMMENT '人员人脸',
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='用户';

-- ----------------------------
-- Records of u_user
-- ----------------------------

-- ----------------------------
-- Table structure for u_user_attr
-- ----------------------------
DROP TABLE IF EXISTS `u_user_attr`;
CREATE TABLE `u_user_attr` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'id',
  `attr_id` varchar(30) NOT NULL COMMENT '属性id',
  `user_id` varchar(30) NOT NULL COMMENT '用户ID',
  `spec_cd` varchar(12) NOT NULL COMMENT '规格id,参考spec表',
  `value` varchar(50) NOT NULL COMMENT '属性值',
  `b_id` varchar(30) DEFAULT NULL COMMENT '业务ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0在用，1失效',
  PRIMARY KEY (`id`),
  KEY `i_attr_id` (`attr_id`),
  KEY `i_user_id` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of u_user_attr
-- ----------------------------

-- ----------------------------
-- Table structure for unitem_log
-- ----------------------------
DROP TABLE IF EXISTS `unitem_log`;
CREATE TABLE `unitem_log` (
  `b_id` varchar(30) NOT NULL COMMENT '业务Id',
  `o_id` varchar(30) NOT NULL COMMENT '订单ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `service_name` varchar(256) DEFAULT NULL COMMENT '服务名称，事务失败时回滚调用微服务名称',
  `log_text` longtext NOT NULL COMMENT '回滚内容',
  `status_cd` varchar(2) NOT NULL COMMENT '数据状态，详细参考c_status表',
  UNIQUE KEY `b_id` (`b_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of unitem_log
-- ----------------------------

-- ----------------------------
-- Table structure for user_download_file
-- ----------------------------
DROP TABLE IF EXISTS `user_download_file`;
CREATE TABLE `user_download_file` (
  `download_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '下载ID',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '名称',
  `community_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '小区ID',
  `download_user_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户ID',
  `download_user_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户名称',
  `file_type` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '文件类型',
  `state` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '1001' COMMENT '等待 1001 生成中 2002 生成完成 3003',
  `temp_url` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '文件地址',
  `b_id` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '业务ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `remark` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`download_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of user_download_file
-- ----------------------------

-- ----------------------------
-- Table structure for visit
-- ----------------------------
DROP TABLE IF EXISTS `visit`;
CREATE TABLE `visit` (
  `visit_id` varchar(30) NOT NULL COMMENT '拜访ID',
  `name` varchar(255) NOT NULL COMMENT '姓名',
  `visit_gender` varchar(1) NOT NULL COMMENT '性别',
  `phone_number` varchar(11) NOT NULL COMMENT '电话号码',
  `community_id` varchar(30) DEFAULT NULL COMMENT '小区ID',
  `room_name` varchar(64) NOT NULL COMMENT '拜访房屋',
  `room_id` varchar(64) NOT NULL COMMENT '拜访房屋',
  `owner_id` varchar(30) DEFAULT NULL COMMENT '拜访业主',
  `owner_name` varchar(30) DEFAULT NULL COMMENT '拜访业主',
  `type_id` varchar(30) NOT NULL COMMENT '访客类型',
  `visit_case` varchar(255) DEFAULT NULL COMMENT '拜访事由',
  `visit_time` datetime DEFAULT NULL COMMENT '拜访时间',
  `departure_time` datetime DEFAULT NULL COMMENT '访客离开时间',
  `face_path` varchar(256) DEFAULT NULL COMMENT '访客人脸，类型为人脸时 存人脸',
  `qrcode` varchar(256) DEFAULT NULL COMMENT '访客二维码,类型为访客二维码 存二维码信息',
  `state` varchar(10) NOT NULL COMMENT '审核状态 0表示未审核；1表示审核通过；2表示审核拒绝',
  `msg` varchar(255) DEFAULT NULL COMMENT '审核备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `status_cd` varchar(2) NOT NULL COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  PRIMARY KEY (`visit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of visit
-- ----------------------------

-- ----------------------------
-- Table structure for visit_type
-- ----------------------------
DROP TABLE IF EXISTS `visit_type`;
CREATE TABLE `visit_type` (
  `type_id` varchar(30) NOT NULL COMMENT '类型ID',
  `name` varchar(30) NOT NULL COMMENT '类型名称',
  `visit_way` varchar(12) NOT NULL COMMENT '通行方式，FACE 人脸 QRCODE 访客码',
  `audit_way` varchar(12) NOT NULL COMMENT '审核方式，1001 物业审核 2002 业主审核',
  `visit_day` int NOT NULL DEFAULT '1' COMMENT '拜访天数，默认1天',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考t_dict表，0, 在用 1失效',
  PRIMARY KEY (`type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of visit_type
-- ----------------------------
